#include <stdio.h>
#include <string.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <netdb.h>

/* vortex L0: sum the four uint32s the service sends, send it back */
int main(void) {
    int fd, i;
    struct sockaddr_in sa;
    unsigned char buf[16];
    char reply[256];
    unsigned int v[4], sum = 0;
    ssize_t n;

    fd = socket(AF_INET, SOCK_STREAM, 0);
    if (fd < 0) { perror("socket"); return 1; }

    memset(&sa, 0, sizeof(sa));
    sa.sin_family = AF_INET;
    sa.sin_port = htons(5842);
    /* resolve the host name first; inet_pton only takes a literal IP */
    {
        struct hostent *he = gethostbyname("vortex.labs.overthewire.org");
        if (!he) { perror("gethostbyname"); return 1; }
        memcpy(&sa.sin_addr, he->h_addr_list[0], he->h_length);
    }

    if (connect(fd, (struct sockaddr *)&sa, sizeof(sa)) < 0) {
        perror("connect");
        return 1;
    }

    n = 0;
    while (n < 16) {
        ssize_t r = read(fd, buf + n, 16 - n);
        if (r <= 0) { perror("read"); return 1; }
        n += r;
    }

    for (i = 0; i < 4; i++) {
        memcpy(&v[i], buf + 4 * i, 4);
        sum += v[i];
    }

    printf("received: %u %u %u %u\n", v[0], v[1], v[2], v[3]);
    printf("sum:      %u (0x%08x)\n", sum, sum);

    if (write(fd, &sum, 4) != 4) { perror("write"); return 1; }

    /* the reply can arrive in several chunks: read until the peer closes */
    memset(reply, 0, sizeof(reply));
    n = 0;
    while (n < (ssize_t)sizeof(reply) - 1) {
        ssize_t r = read(fd, reply + n, sizeof(reply) - 1 - n);
        if (r <= 0) break;
        n += r;
    }
    reply[n] = 0;
    printf("%s\n", reply);

    close(fd);
    return 0;
}
